using Mbb.Archive.BuildingBlocks.Application;using Mbb.Archive.Modules.Archive.Application.Abstractions;namespace Mbb.Archive.Modules.Archive.Application.Records.Get;public sealed class GetArchiveRecordQueryHandler:IQueryHandler<GetArchiveRecordQuery,ArchiveRecordDetails>{private readonly IArchiveQueries _queries;public GetArchiveRecordQueryHandler(IArchiveQueries queries){_queries=queries;}public async Task<Result<ArchiveRecordDetails>> Handle(GetArchiveRecordQuery q,CancellationToken ct){var r=await _queries.GetAsync(q.Id,ct);return r is null?Result<ArchiveRecordDetails>.Failure(Error.NotFound("archive.record_not_found","Archive record was not found.")):Result<ArchiveRecordDetails>.Success(r);}}
